def add_business_time(start_dt_utc: datetime, hours: float) -> datetime:
    dt = start_dt_utc.astimezone(WARSAW_TZ)
    def get_next_business_day_start(d: datetime) -> datetime:
        d += timedelta(days=1)
        while d.weekday() >= 5:
            d += timedelta(days=1)
        return d.replace(hour=8, minute=0, second=0, microsecond=0, tzinfo=WARSAW_TZ)

    if dt.weekday() >= 5 or dt.time() >= time(16, 0, 0):
        dt = get_next_business_day_start(dt.replace(hour=16, minute=0, second=0, microsecond=0, tzinfo=WARSAW_TZ))
    elif dt.time() < time(8, 0, 0):
        dt = dt.replace(hour=8, minute=0, second=0, microsecond=0, tzinfo=WARSAW_TZ)
        
    remaining_hours = hours
    while remaining_hours > 0:
        end_of_day = dt.replace(hour=16, minute=0, second=0, microsecond=0, tzinfo=WARSAW_TZ)
        hours_to_end = (end_of_day - dt).total_seconds() / 3600
        
        if remaining_hours <= hours_to_end:
            dt += timedelta(hours=remaining_hours)
            remaining_hours = 0
        else:
            remaining_hours -= hours_to_end
            dt = get_next_business_day_start(dt)
            
    return dt.astimezone(timezone.utc)

def calculate_sla(priority: str, created_at: datetime):
    if priority == "P1":
        return {
            "ack_due_at": format_iso(created_at + timedelta(minutes=15)),
            "resolve_due_at": format_iso(created_at + timedelta(hours=4))
        }
    sla_map = {"P2": (1, 8), "P3": (4, 24), "P4": (8, 72)}
    ack_hours, res_hours = sla_map[priority]
    return {
        "ack_due_at": format_iso(add_business_time(created_at, ack_hours)),
        "resolve_due_at": format_iso(add_business_time(created_at, res_hours))
    }

