@app.post("/dora/metrics")
async def calculate_metrics(request: Request):
    try:
        body = await request.json()
    except Exception:
        raise HTTPException(status_code=400, detail={"error": {"code": "bad_request", "message": "Invalid JSON"}})

    if not isinstance(body, dict) or "window" not in body or "events" not in body:
        raise HTTPException(status_code=400, detail={"error": {"code": "bad_request", "message": "Missing window or events"}})
    
    events = body["events"]
    if not isinstance(events, list):
        raise HTTPException(status_code=400, detail={"error": {"code": "bad_request", "message": "Events must be an array"}})

    try:
        w_from = parse_iso_ts(body["window"]["from"])
        w_to = parse_iso_ts(body["window"]["to"])
        if w_to <= w_from: 
            raise ValueError("Invalid window timeframe")
    except Exception:
        raise HTTPException(status_code=400, detail={"error": {"code": "bad_request", "message": "Invalid window"}})

    # Well-formedness check & deduplication
    seen_ids, shas, dep_ids, inc_ids, inc_opened, inc_resolved = set(), set(), set(), set(), set(), set()
    dedup_events = []
    
    for ev in events:
        if not isinstance(ev, dict) or "type" not in ev or "at" not in ev:
            raise HTTPException(status_code=422, detail={"error": {"code": "invalid_event", "message": "Malformed event"}})
        eid = ev.get("event_id")
        if not eid: 
            raise HTTPException(status_code=422, detail={"error": {"code": "invalid_event", "message": "Missing event_id"}})
        
        t = ev["type"]
        if t == "commit": shas.add(ev.get("sha"))
        elif t == "deployment": dep_ids.add(ev.get("deployment_id"))
        elif t == "incident":
            inc_ids.add(ev.get("incident_id"))
            if ev.get("phase") == "opened": inc_opened.add(ev.get("incident_id"))
            elif ev.get("phase") == "resolved": inc_resolved.add(ev.get("incident_id"))
            
        if eid not in seen_ids:
            seen_ids.add(eid)
            dedup_events.append(ev)

    if not inc_resolved.issubset(inc_opened):
        raise HTTPException(status_code=422, detail={"error": {"code": "invalid_incident", "message": "Incident resolved without opened"}})

    for ev in dedup_events:
        t = ev["type"]
        if t == "commit":
            if ev.get("reverts") is not None and ev["reverts"] not in shas:
                raise HTTPException(status_code=422, detail={"error": {"code": "invalid_commit", "message": "Invalid reverts"}})
            if (ev.get("reverts") is not None) == (ev.get("change_id") is not None):
                raise HTTPException(status_code=422, detail={"error": {"code": "invalid_commit", "message": "Invalid change_id/reverts logic"}})
        elif t == "deployment":
            for c in ev.get("commits", []):
                if c not in shas: 
                    raise HTTPException(status_code=422, detail={"error": {"code": "invalid_deployment", "message": "Invalid commit"}})
        elif t == "incident":
            for d in ev.get("deployments", []):
                if d not in dep_ids: 
                    raise HTTPException(status_code=422, detail={"error": {"code": "invalid_incident", "message": "Invalid deployment"}})

    # Calculations
    commits = {}
    incidents = []
    prod_deployments = []
    revert_chains_collapsed = 0

    for ev in dedup_events:
        ev["_ts"] = parse_iso_ts(ev["at"])
        if ev["type"] == "commit":
            commits[ev["sha"]] = ev
            if ev.get("reverts"): revert_chains_collapsed += 1
        elif ev["type"] == "deployment" and ev.get("environment") == "production":
            prod_deployments.append(ev)
        elif ev["type"] == "incident":
            incidents.append(ev)

    def get_change_id(sha):
        visited, curr = set(), sha
        while curr in commits:
            if curr in visited: break
            visited.add(curr)
            if commits[curr].get("reverts"): curr = commits[curr]["reverts"]
            else: return commits[curr].get("change_id")
        return None

    changes_first_commit = {}
    all_changes = set()
    for sha, c in commits.items():
        cid = get_change_id(sha)
        if cid:
            all_changes.add(cid)
            if cid not in changes_first_commit or c["_ts"] < changes_first_commit[cid]:
                changes_first_commit[cid] = c["_ts"]

    deps_in_window = sorted([d for d in prod_deployments if w_from <= d["_ts"] < w_to], key=lambda x: x["_ts"])
    successful_deps = [d for d in deps_in_window if d.get("outcome") == "success"]
    failed_deps = [d for d in deps_in_window if d.get("outcome") == "failure"]

    lead_time_pairs = []
    negative_lead_time_pairs = 0
    commits_never_on_main = set()
    deployments_without_commits = 0
    first_deployment_of_commit = {}

    for dep in deps_in_window:
        dep_commits = dep.get("commits", [])
        if not dep_commits: deployments_without_commits += 1
        for sha in dep_commits:
            if sha in commits and commits[sha].get("branch") != "main": commits_never_on_main.add(sha)

    for dep in successful_deps:
        for sha in dep.get("commits", []):
            if sha not in first_deployment_of_commit:
                first_deployment_of_commit[sha] = dep["_ts"]
                if sha in commits:
                    lt = dep["_ts"] - commits[sha]["_ts"]
                    if lt < 0:
                        negative_lead_time_pairs += 1
                        lt = 0
                    lead_time_pairs.append(lt)

    incident_dict = {}
    for inc in incidents:
        iid = inc["incident_id"]
        if iid not in incident_dict: incident_dict[iid] = {"opened": None, "resolved": None, "deployments": []}
        if inc.get("phase") == "opened":
            incident_dict[iid]["opened"] = inc["_ts"]
            incident_dict[iid]["deployments"] = inc.get("deployments", [])
        elif inc.get("phase") == "resolved":
            incident_dict[iid]["resolved"] = inc["_ts"]

    recovered_failures, open_failures = 0, 0
    recovery_times = []

    for dep in failed_deps:
        covering = None
        for iid, idata in incident_dict.items():
            if idata["opened"] is not None and dep["deployment_id"] in idata["deployments"]:
                if not covering or idata["opened"] < covering[1]["opened"] or (idata["opened"] == covering[1]["opened"] and iid < covering[0]):
                    covering = (iid, idata)
        if covering and covering[1]["resolved"] is not None:
            recovered_failures += 1
            rt = covering[1]["resolved"] - dep["_ts"]
            recovery_times.append(rt if rt >= 0 else 0)
        else:
            open_failures += 1

    intervals = [(iid, d["opened"], d["resolved"] if d["resolved"] is not None else w_to) for iid, d in incident_dict.items() if d["opened"] is not None]
    overlapping_incidents = sum(1 for i in range(len(intervals)) for j in range(i+1, len(intervals)) if intervals[i][1] < intervals[j][2] and intervals[j][1] < intervals[i][2])

    days = (w_to - w_from) / 86400.0
    freq = len(deps_in_window) / days if days > 0 else 0.0
    cfr = len(failed_deps) / len(deps_in_window) if deps_in_window else None
    rework_deps = [d for d in deps_in_window if d.get("unplanned") is True and d.get("caused_by") is not None]
    rwr = len(rework_deps) / len(deps_in_window) if deps_in_window else None

    change_first_success = {}
    for dep in successful_deps:
        for sha in dep.get("commits", []):
            cid = get_change_id(sha)
            if cid and cid not in change_first_success:
                change_first_success[cid] = dep["_ts"]

    true_lead_times = [max(0, change_first_success[cid] - changes_first_commit[cid]) for cid in change_first_success if cid in changes_first_commit]

    return JSONResponse(content={
        "spec_version": "1.0.0",
        "window": body["window"],
        "deployment_frequency_per_day": round_6_dec(freq),
        "change_lead_time_seconds_p50": get_median(lead_time_pairs),
        "failed_deployment_recovery_time_seconds_p50": get_median(recovery_times),
        "change_fail_rate": round_6_dec(cfr) if cfr is not None else None,
        "deployment_rework_rate": round_6_dec(rwr) if rwr is not None else None,
        "counts": {
            "deployments": len(deps_in_window), "successful_deployments": len(successful_deps),
            "failed_deployments": len(failed_deps), "recovered_failures": recovered_failures,
            "open_failures": open_failures, "rework_deployments": len(rework_deps),
            "lead_time_pairs": len(lead_time_pairs), "changes": len(all_changes)
        },
        "anomalies": {
            "negative_lead_time_pairs": negative_lead_time_pairs, "deployments_without_commits": deployments_without_commits,
            "commits_never_on_main": len(commits_never_on_main), "revert_chains_collapsed": revert_chains_collapsed,
            "overlapping_incident_pairs": overlapping_incidents
        },
        "ground_truth": {
            "changes_delivered": len(change_first_success), "true_change_lead_time_seconds_p50": get_median(true_lead_times)
        }
    })